func newFiscalPeriod() unsafe.Pointer { return unsafe.Pointer(new(fiscalperiod.FiscalPeriod)) }

func newNFiscalPeriod(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]fiscalperiod.FiscalPeriod, n)))
}

func ptrFiscalPeriod(p unsafe.Pointer, c int32) any {
	r := (*fiscalperiod.FiscalPeriod)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.FiscalYearID))
	case 4:
		return (*int64)(unsafe.Pointer(&r.PeriodNumber))
	case 5:
		return (*string)(unsafe.Pointer(&r.PeriodType))
	case 6:
		return (*string)(unsafe.Pointer(&r.Status))
	case 7:
		return &r.Name
	case 8:
		return &r.StartDate
	case 9:
		return &r.EndDate
	case 10:
		return &r.IsAdjusting
	case 11:
		return &r.AllowAdjustingEntries
	case 12:
		return &r.AdjustmentDeadline
	case 13:
		return &r.LockedAt
	case 14:
		return (*string)(unsafe.Pointer(&r.LockedByID))
	case 15:
		return &r.ClosedAt
	case 16:
		return (*string)(unsafe.Pointer(&r.ClosedByID))
	case 17:
		return &r.ReopenedAt
	case 18:
		return (*string)(unsafe.Pointer(&r.ReopenedByID))
	case 19:
		return &r.ReopenReason
	case 20:
		return &r.Version
	case 21:
		return &r.CreatedAt
	case 22:
		return &r.UpdatedAt
	case 23:
		return &r.SearchVector
	case 24:
		return &r.Rank
	}
	return nil
}

func valueFiscalPeriod(p unsafe.Pointer, c int32) any {
	r := (*fiscalperiod.FiscalPeriod)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.FiscalYearID)
	case 4:
		return int64(r.PeriodNumber)
	case 5:
		return string(r.PeriodType)
	case 6:
		return string(r.Status)
	case 7:
		return r.Name
	case 8:
		return r.StartDate
	case 9:
		return r.EndDate
	case 10:
		return r.IsAdjusting
	case 11:
		return r.AllowAdjustingEntries
	case 12:
		if r.AdjustmentDeadline == nil {
			return nil
		}
		return *r.AdjustmentDeadline
	case 13:
		if r.LockedAt == nil {
			return nil
		}
		return *r.LockedAt
	case 14:
		if r.LockedByID == "" {
			return nil
		}
		return string(r.LockedByID)
	case 15:
		if r.ClosedAt == nil {
			return nil
		}
		return *r.ClosedAt
	case 16:
		if r.ClosedByID == "" {
			return nil
		}
		return string(r.ClosedByID)
	case 17:
		if r.ReopenedAt == nil {
			return nil
		}
		return *r.ReopenedAt
	case 18:
		if r.ReopenedByID == "" {
			return nil
		}
		return string(r.ReopenedByID)
	case 19:
		if r.ReopenReason == "" {
			return nil
		}
		return r.ReopenReason
	case 20:
		return r.Version
	case 21:
		return r.CreatedAt
	case 22:
		return r.UpdatedAt
	case 23:
		return r.SearchVector
	case 24:
		return r.Rank
	}
	return nil
}

func attachFiscalPeriod(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*fiscalperiod.FiscalPeriod)(p)
	switch rel {
	case 0:
		r.ClosedBy = (*tenant.User)(child)
	case 1:
		r.LockedBy = (*tenant.User)(child)
	case 2:
		r.ReopenedBy = (*tenant.User)(child)
	}
}

func beforeCreateFiscalPeriod(ctx context.Context, p unsafe.Pointer) error {
	return (*fiscalperiod.FiscalPeriod)(p).BeforeCreate(ctx)
}

